#!/usr/bin/env python3
"""Apply the bounded, test-first PR 125 backend approval phrase repair."""

from __future__ import annotations

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
COMMANDS = ROOT / "src-tauri/src/commands.rs"
CONTRACT_TEST = ROOT / "src-tauri/tests/cloud_transfer_coverage_contract.rs"
API = ROOT / "src/lib/api.ts"
API_TEST = ROOT / "src/lib/api.test.ts"
ARCHIVE = ROOT / "src/lib/CloudArchive.svelte"
WORKFLOW = ROOT / ".github/workflows/repair-pr125-backend-approval-phrases.yml"
SCRIPT = Path(__file__).resolve()

TEST_NAME = "cloud_copy_approval_phrases_are_backend_owned"
TEST_SOURCE = r'''

/// Verifies that approval phrases are generated by Rust and only selected by TypeScript.
#[test]
fn cloud_copy_approval_phrases_are_backend_owned() {
    let commands = include_str!("../src/commands.rs");
    let api = include_str!("../../src/lib/api.ts");
    let archive = include_str!("../../src/lib/CloudArchive.svelte");

    assert!(
        commands.contains("cloud_transfer::cloud_copy_approval_phrase("),
        "the Tauri plan output must obtain exact phrases from the Rust approval function"
    );
    assert!(
        commands.contains("copy_approval_phrases"),
        "the Tauri plan output must publish backend-owned phrases"
    );
    assert!(
        !api.contains("`DiskSage cloud ${action} ${candidate.review_fingerprint} 승인`"),
        "TypeScript must not duplicate the security-sensitive approval format"
    );
    assert!(
        api.contains("phrase_sets[candidate.review_fingerprint]"),
        "TypeScript must select the backend-returned phrase by exact review fingerprint"
    );
    assert!(
        archive.contains("report?.copy_approval_phrases ?? {}"),
        "the UI must read the phrases from the current plan response"
    );
}
'''


def replace_once(path: Path, old: str, new: str) -> None:
    """Replace exactly one audited fragment in a UTF-8 source file."""
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected one anchor in {path}, found {count}: {old[:100]!r}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def add_test() -> None:
    """Append the regression before modifying production sources."""
    text = CONTRACT_TEST.read_text(encoding="utf-8")
    if TEST_NAME in text:
        raise SystemExit("backend ownership regression already exists")
    CONTRACT_TEST.write_text(text + TEST_SOURCE, encoding="utf-8")


def apply_repair() -> None:
    """Route security-sensitive phrases from Rust to the TypeScript UI."""
    replace_once(
        COMMANDS,
        '''/// Read-only cloud offload plan. The selected destination must be one of the roots discovered
/// on this machine; this command never creates a folder or moves a file.
#[cfg(not(coverage))]
#[tauri::command(async)]
pub async fn plan_cloud_archive(
    root: String,
    cloud_root: String,
    min_size_mib: u64,
    min_age_days: u64,
    limit: usize,
    app: AppHandle,
) -> Result<cloud::CloudPlanReport, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, report) =
            cloud_plan_for_inputs(&root, &cloud_root, min_size_mib, min_age_days, limit, &app)?;
        Ok(report)
    })
    .await
    .map_err(|_| "cloud-plan-task-failed".to_string())?
}
''',
        '''/// Backend-generated exact approval phrases for one immutable review fingerprint.
#[cfg(not(coverage))]
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct CloudCopyApprovalPhraseSet {
    /// Phrase required before a copy-only action can be authorized.
    pub copy_only: String,
    /// Phrase required before an existing destination can be adopted.
    pub adopt_existing_copy: String,
}

/// Read-only cloud plan plus backend-owned approval phrases keyed by review fingerprint.
#[cfg(not(coverage))]
#[derive(Debug, Clone, serde::Serialize)]
pub struct CloudPlanOutput {
    /// Existing cloud plan fields remain flattened for wire compatibility.
    #[serde(flatten)]
    pub report: cloud::CloudPlanReport,
    /// Exact phrases generated by the same Rust function used during authorization.
    pub copy_approval_phrases:
        std::collections::BTreeMap<String, CloudCopyApprovalPhraseSet>,
}

/// Read-only cloud offload plan. The selected destination must be one of the roots discovered
/// on this machine; this command never creates a folder or moves a file.
#[cfg(not(coverage))]
#[tauri::command(async)]
pub async fn plan_cloud_archive(
    root: String,
    cloud_root: String,
    min_size_mib: u64,
    min_age_days: u64,
    limit: usize,
    app: AppHandle,
) -> Result<CloudPlanOutput, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let (_, report) =
            cloud_plan_for_inputs(&root, &cloud_root, min_size_mib, min_age_days, limit, &app)?;
        let copy_approval_phrases = report
            .candidates
            .iter()
            .map(|candidate| {
                (
                    candidate.review_fingerprint.clone(),
                    CloudCopyApprovalPhraseSet {
                        copy_only: cloud_transfer::cloud_copy_approval_phrase(
                            candidate,
                            cloud_transfer::CloudCopyApprovalAction::CopyOnly,
                        ),
                        adopt_existing_copy: cloud_transfer::cloud_copy_approval_phrase(
                            candidate,
                            cloud_transfer::CloudCopyApprovalAction::AdoptExistingCopy,
                        ),
                    },
                )
            })
            .collect();
        Ok(CloudPlanOutput {
            report,
            copy_approval_phrases,
        })
    })
    .await
    .map_err(|_| "cloud-plan-task-failed".to_string())?
}
''',
    )

    replace_once(
        API,
        '''export type CloudCopyApprovalAction = "copy-only" | "adopt-existing-copy";

export interface CloudCopyApproval {
''',
        '''export type CloudCopyApprovalAction = "copy-only" | "adopt-existing-copy";

export interface CloudCopyApprovalPhraseSet {
  copy_only: string;
  adopt_existing_copy: string;
}

export interface CloudCopyApproval {
''',
    )
    replace_once(
        API,
        '''export interface CloudPlanReport {
  cloud_root: CloudRoot;
  generated_at_ms: number;
  candidates: CloudCandidate[];
''',
        '''export interface CloudPlanReport {
  cloud_root: CloudRoot;
  generated_at_ms: number;
  copy_approval_phrases: Record<string, CloudCopyApprovalPhraseSet>;
  candidates: CloudCandidate[];
''',
    )
    replace_once(
        API,
        '''export const cloudCopyApprovalPhrase = (
  candidate: Pick<CloudCandidate, "review_fingerprint">,
  action: CloudCopyApprovalAction,
) => `DiskSage cloud ${action} ${candidate.review_fingerprint} 승인`;
''',
        '''export const cloudCopyApprovalPhrase = (
  candidate: Pick<CloudCandidate, "review_fingerprint">,
  action: CloudCopyApprovalAction,
  phrase_sets: Readonly<Record<string, CloudCopyApprovalPhraseSet>>,
): string | null => {
  const phrases = phrase_sets[candidate.review_fingerprint];
  if (!phrases) return null;
  return action === "copy-only" ? phrases.copy_only : phrases.adopt_existing_copy;
};
''',
    )

    replace_once(
        ARCHIVE,
        '''  function reviewDecision(candidate: api.CloudCandidate): api.CloudReviewDecision | null {
''',
        '''  function copyApprovalPhrase(
    candidate: api.CloudCandidate,
    action: api.CloudCopyApprovalAction,
  ): string | null {
    return api.cloudCopyApprovalPhrase(
      candidate,
      action,
      report?.copy_approval_phrases ?? {},
    );
  }

  function reviewDecision(candidate: api.CloudCandidate): api.CloudReviewDecision | null {
''',
    )
    replace_once(
        ARCHIVE,
        '''    if (exactConfirmationPhrase !== api.cloudCopyApprovalPhrase(candidate, "copy-only")
      || !approvalRationale) return;
''',
        '''    const expectedPhrase = copyApprovalPhrase(candidate, "copy-only");
    if (!expectedPhrase || exactConfirmationPhrase !== expectedPhrase || !approvalRationale) return;
''',
    )
    replace_once(
        ARCHIVE,
        '''    if (exactConfirmationPhrase
        !== api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy")
      || !approvalRationale) return;
''',
        '''    const expectedPhrase = copyApprovalPhrase(candidate, "adopt-existing-copy");
    if (!expectedPhrase || exactConfirmationPhrase !== expectedPhrase || !approvalRationale) return;
''',
    )
    replace_once(
        ARCHIVE,
        '<code>{api.cloudCopyApprovalPhrase(candidate, "copy-only")}</code>',
        '<code>{copyApprovalPhrase(candidate, "copy-only") ?? "승인 문구를 불러오지 못했습니다."}</code>',
    )
    replace_once(
        ARCHIVE,
        '''                    || (copyConfirmations[candidate.metadata_fingerprint] ?? "").trim()
                      !== api.cloudCopyApprovalPhrase(candidate, "copy-only")}
''',
        '''                    || !copyApprovalPhrase(candidate, "copy-only")
                    || (copyConfirmations[candidate.metadata_fingerprint] ?? "").trim()
                      !== copyApprovalPhrase(candidate, "copy-only")}
''',
    )
    replace_once(
        ARCHIVE,
        '<code>{api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy")}</code>',
        '<code>{copyApprovalPhrase(candidate, "adopt-existing-copy") ?? "승인 문구를 불러오지 못했습니다."}</code>',
    )
    replace_once(
        ARCHIVE,
        '''                    || (copyConfirmations[candidate.metadata_fingerprint] ?? "").trim()
                      !== api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy")}
''',
        '''                    || !copyApprovalPhrase(candidate, "adopt-existing-copy")
                    || (copyConfirmations[candidate.metadata_fingerprint] ?? "").trim()
                      !== copyApprovalPhrase(candidate, "adopt-existing-copy")}
''',
    )

    replace_once(
        API_TEST,
        '''describe("cloud copy approval phrase", () => {
  it("binds the exact review fingerprint and requested action", () => {
    const candidate = { review_fingerprint: "a".repeat(64) };
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only")).toBe(
      `DiskSage cloud copy-only ${"a".repeat(64)} 승인`,
    );
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy")).toBe(
      `DiskSage cloud adopt-existing-copy ${"a".repeat(64)} 승인`,
    );
  });
});
''',
        '''describe("cloud copy approval phrase", () => {
  it("selects the backend-returned phrase for the exact review fingerprint", () => {
    const reviewFingerprint = "a".repeat(64);
    const candidate = { review_fingerprint: reviewFingerprint };
    const phraseSets = {
      [reviewFingerprint]: {
        copy_only: "backend copy-only approval",
        adopt_existing_copy: "backend existing-copy adoption",
      },
    };
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only", phraseSets)).toBe(
      "backend copy-only approval",
    );
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy", phraseSets)).toBe(
      "backend existing-copy adoption",
    );
  });

  it("fails closed when the backend omitted the exact fingerprint", () => {
    const candidate = { review_fingerprint: "b".repeat(64) };
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only", {})).toBeNull();
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy", {})).toBeNull();
  });
});
''',
    )


def cleanup() -> None:
    """Remove the one-shot workflow and helper after exact-head validation."""
    for path in (WORKFLOW, SCRIPT):
        if not path.exists():
            raise SystemExit(f"expected one-shot path to exist: {path}")
    WORKFLOW.unlink()
    SCRIPT.unlink()


def main() -> None:
    """Run one repair phase selected by the exact-head workflow."""
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=("add-test", "apply", "cleanup"))
    args = parser.parse_args()
    if args.phase == "add-test":
        add_test()
    elif args.phase == "apply":
        apply_repair()
    else:
        cleanup()


if __name__ == "__main__":
    main()
